class AdaptiveHarvestCap(Contract):
    VERSION = 1

    # UNIMPLEMENTABLE: "publicly acknowledge the violation in the next discussion"
    # UNIMPLEMENTABLE: "commit to honest reporting of our catches after each month and to using the discussion to coordinate restraint rather than compete"

    def __init__(self, num_agents, agent_names, *, prior_state=None):
        super().__init__(num_agents, agent_names, prior_state=prior_state)

    def on_round_start(self, month, fish_population, ctx) -> None:
        pass

    def resolve(self, month, fish_population, submissions, ctx) -> dict[str, float]:
        if fish_population < 25:
            cap = 3.0
        elif fish_population < 50:
            cap = 4.0
        else:
            cap = 5.0

        final_catches = {}
        for name in self.agent_names:
            submitted = float(submissions.get(name, 0.0))
            if submitted > cap:
                ctx.graduated_sanction(
                    name,
                    base_amount=0.0,
                    key="harvest_cap_violation",
                    reason=f"Submitted catch {submitted} exceeds monthly cap of {cap}"
                )
            final_catches[name] = min(submitted, cap)

        return final_catches

    def on_round_end(self, month, fish_population_after, final_catches, ctx) -> None:
        pass
